/// <summary>
        /// Consulta los elementos con determinado numero de embarque.
        /// </summary>
        /// <param name="idEmbarque"></param>
        /// <param name="usuario"></param>
        /// <returns></returns>
        public List<ConsumoSellosPlanta> ConsultarElementosEmbarque(int idEmbarque, string usuario)
        {
            _persistencia.Usuario = usuario;
            List<ConsumoSellosPlanta> lista = new List<ConsumoSellosPlanta> { };
            Consulta consulta = GetConsulta();
            consulta.CondicionesWhere = new List<CondicionWhere>
            {
                new CondicionWhere(_alias + ".AU_BORRADO", Operadores.IGUAL, 0 ,false, OperadorLogico.AND),
                new CondicionWhere(_alias + ".FK_EMBARQUE_ESPUELA", Operadores.IGUAL, idEmbarque, true),
            };

            DataSet ds = _persistencia.Consultar(consulta);

            foreach (DataRow row in ds.Tables[0].Rows)
            {
                lista.Add(toObject(row));
            }
            return lista;
        }

public void EstablecerTipoCambio(List<CompraPrecargadaDetalle> ListaFacturas, string usuario)
        {
            try
            {
                _persistencia.Usuario = usuario;
                _persistencia.BeginTrans();

                foreach (var item in ListaFacturas)
                {
                    Consulta consulta = new Consulta("DI_TR_COMPRAS_PRECARGADAS_DET");
                    consulta.CamposValor = new Dictionary<string, object>();

                    consulta.CamposValor.Add("TIPO_CAMBIO", item.Tipo_Cambio);
                    consulta.CamposValor.Add("AU_USUARIO",usuario);
                    consulta.CamposValor.Add("AU_FECHA_MOD", "CURRENT DATE");
                    consulta.CamposValor.Add("AU_HORA_MOD", "CURRENT TIME");

                    consulta.CondicionesWhere = new List<CondicionWhere>
                    {
                        new CondicionWhere("PK_COMPRA_PRECARGADA_DET", Operadores.IGUAL, item.Id.Pk_Compra_Precargada_Det, false)
                    };

                    _persistencia.Modificar(consulta, _persistencia.Trans);
                }

                _persistencia.CommitTrans();

            }
            catch (Exception ex)
            {
                _persistencia.RollbackTrans();
                throw ex;
            }
        }

