        /// <summary>
        /// Consulta los elementos CompraPrecargada que coincidan con los criterios de busqueda 
        /// </summary>
        /// <param name="criteriosAplicados"></param>
        /// <param name="usuario"></param>
        /// <returns></returns>
        public List<CompraPrecargada> ConsultarElementos(List<CriterioValor> criteriosAplicados, string usuario)
        {
            _persistencia.Usuario = usuario;
            List<CompraPrecargada> lista = new List<CompraPrecargada>  { };
            Consulta consulta = GetConsulta();

            if (criteriosAplicados.Count > 0)
            {
                consulta.CondicionesWhere = UtileriasBB.ObtenerCriteriosBusqueda(criteriosAplicados, false, _alias);
            }

            DataSet ds = _persistencia.Consultar(consulta);

            if (ds.Tables[0].Rows.Count > 0)
            {
                lista.AddRange(from DataRow row in ds.Tables[0].Rows select toObject(row));
            }
            return lista;
        }

