        /// <returns></returns>
        private Consulta GetConsultaDetalle()
        {
            Consulta consulta = new Consulta("TR_TR_INFRACCIONES_DET AS DETALLE")
            {
                Campos = string.Format(@"
                    DETALLE.AU_BORRADO,
	                DETALLE.AU_FECHA_MOD,
	                DETALLE.AU_HORA_MOD,
	                DETALLE.AU_TERMINAL,
	                DETALLE.AU_USUARIO,
                    DETALLE.PK_INFRACCION_DET,
	                DETALLE.CLAVE,
	                DETALLE.MOTIVO,
	                DETALLE.IMPORTE,
	                DETALLE.IMPORTE_CONDUCTOR,
	                DETALLE.IMPORTE_EMPRESA,
	                DETALLE.ESTATUS,
	                DETALLE.FK_PERSONAL_REGISTRA,
	                REGISTRA.NOMBRE_COMPLETO AS PERSONAL_REGISTRA,
	                DETALLE.FK_PERSONAL_CANCELA,
	                CANCELA.NOMBRE_COMPLETO AS PERSONAL_CANCELA
                "),
                CondicionesJoin = new List<CondicionJoin>
                {
                    new CondicionJoin(TipoJoin.INNER, "TR_TR_INFRACCIONES AS INFRACCION")
                    { CamposCondicion = new List<CamposCondicion> { new CamposCondicion("DETALLE.FK_INFRACCION", Operadores.IGUAL, "INFRACCION.PK_INFRACCION", true) } },
                    new CondicionJoin(TipoJoin.INNER, "BB_CT_PERSONAL AS REGISTRA")
                    { CamposCondicion = new List<CamposCondicion> { new CamposCondicion("DETALLE.FK_PERSONAL_REGISTRA", Operadores.IGUAL, "REGISTRA.PK_PERSONAL", true) } },
                    new CondicionJoin(TipoJoin.LEFT, "BB_CT_PERSONAL AS CANCELA")
                    { CamposCondicion = new List<CamposCondicion> { new CamposCondicion("DETALLE.FK_PERSONAL_CANCELA", Operadores.IGUAL, "CANCELA.PK_PERSONAL", true) } },
                },
                Orderby = "DETALLE.PK_INFRACCION_DET DESC",
            };
            return consulta;
        }

/// <summary>
        /// consulta rendimiento del conductor
        /// </summary>
        /// <param name="pag"></param>
        /// <returns></returns>
        private static Consulta GetRendimiento(string pag)
        {
            Consulta consulta = new Consulta("TR_TR_LIQUIDACIONES AS LIQUIDACION")
            {
                Campos = string.Format(@"
                CONDUCTOR.PK_CONDUCTOR,
                CONDUCTOR.NO_NOMINA,
	            CONDUCTOR.FOTOGRAFIA,
	            CONDUCTOR.NOMBRE_COMPLETO,
	            --LIQUIDACION.RENDIMIENTO_VIAJE,
                AVG( (LIQUIDACION.KILOMETRAJE / LIQUIDACION.LITROS_CONSUMIDOS) ) PROMEDIO_REAL,
	            AVG( (LIQUIDACION.KILOMETRAJE / LIQUIDACION.LITROS_CONSUMIDOS_CUMMINS) ) PROMEDIO_CUMMINS
                "),

                CondicionesJoin = new List<CondicionJoin>
                {
                    new CondicionJoin(TipoJoin.INNER, "TR_TR_VIAJES AS VIAJE")
                    { CamposCondicion = new List<CamposCondicion> { new CamposCondicion("LIQUIDACION.FK_VIAJE", Operadores.IGUAL, "VIAJE.PK_VIAJE", true) } },
                    new CondicionJoin(TipoJoin.INNER, "BB_CT_CONDUCTORES AS CONDUCTOR")
                    { CamposCondicion = new List<CamposCondicion> { new CamposCondicion("VIAJE.FK_CONDUCTOR", Operadores.IGUAL, "CONDUCTOR.PK_CONDUCTOR", true) } },
                    new CondicionJoin(TipoJoin.INNER, "BB_CT_EMPRESAS AS EMPRESA")
                    { CamposCondicion = new List<CamposCondicion> { new CamposCondicion("CONDUCTOR.FK_EMPRESA_ASIGNADA", Operadores.IGUAL, "EMPRESA.PK_EMPRESA", true) } },
                    new CondicionJoin(TipoJoin.INNER, "BB_CT_SUCURSALES AS SUCURSAL")
                    { CamposCondicion = new List<CamposCondicion> { new CamposCondicion("EMPRESA.PK_EMPRESA", Operadores.IGUAL, "SUCURSAL.FK_EMPRESA", true) } },
                },
                Groupby = "CONDUCTOR.PK_CONDUCTOR, CONDUCTOR.NO_NOMINA, CONDUCTOR.FOTOGRAFIA, CONDUCTOR.NOMBRE_COMPLETO",
                Orderby = "CONDUCTOR.NOMBRE_COMPLETO " + pag,
            };

            return consulta;
