/// <summary>
        /// Consulta los elementos en base a los criterios
        /// </summary>
        /// <param name="criteriosAplicados"></param>
        /// <param name="usuario"></param>
        /// <returns></returns>
        public List<ParametroTrafico> ConsultarElementos(List<CriterioValor> criteriosAplicados, string usuario)
        {
            _persistencia.Usuario = usuario;
            List<ParametroTrafico> lista = new List<ParametroTrafico> { };
            Consulta consulta = GetConsulta();

            if (criteriosAplicados.Count > 0)
                consulta.CondicionesWhere = UtileriasBB.ObtenerCriteriosBusqueda(criteriosAplicados, false, null);

            consulta.CondicionesWhere.Add(new CondicionWhere("PARAMETRO.ESTATUS", Operadores.IGUAL,StringEnum.GetStringValue(EstatusParametroTrafico.ACTIVO), false, OperadorLogico.AND));
            consulta.CondicionesWhere.Add(new CondicionWhere("PARAMETRO.AU_BORRADO", Operadores.IGUAL, 0, false));

            DataSet ds = _persistencia.Consultar(consulta);

            foreach (DataRow row in ds.Tables[0].Rows)
            {
                lista.Add(toObject(row));
            }

            return lista;
        }

