        /// <summary>
        /// Metodo que determina valida las liquidaciones del conductor.
        /// </summary>
        /// <param name="idConductor"></param>
        /// <param name="usuario"></param>
        /// <returns>
        /// Validación de las liquidaciones,
        /// Número liquidaciones permitidas,
        /// Número liquidaciones pendientes,
        /// Folios viajes que exceden fecha permitida,
        /// Lista viajes que exceden fecha permitida</returns>
        public (bool,int,int,string,List<Viaje>) LiquidacionesPendientesConductor(IDConductor idConductor, Usuario usuario)
        {
            try
            {
                var validacion = true;

                //Variable de sistema con liquidaciones permitidas.
                var serviceVariableSistema = new NVariableSistema();
                var variableSistema = serviceVariableSistema.ConsultarElemento("LIQPEN", "INDICA EL NÚMERO DE LIQUIDACIONES PENDIENTES PERMITIDAS", 0, "3,CORP|3,GIR|6,DIR", true, usuario.Id.Login);

                //Número de liquidaciones permitidas.
                var liquidacionesPermitidas = 0;
                variableSistema.Valor_String.Split('|').ToList().ForEach(i =>
                {
                    if (i.Split(',')[1] == usuario.Id.Personal.Sucursal.jurisdiccionTrafico)
                        liquidacionesPermitidas = Convert.ToInt32(i.Split(',')[0]);
                });

                //Obtener liquidaciones pendientes del conductor.
                var liquidacionesPendientes = DViajesGastos.LiquidacionesPendientes(idConductor, usuario.Id.Login);

                if (liquidacionesPendientes.Count() == 0)
                    return (true,liquidacionesPermitidas,0,string.Empty,liquidacionesPendientes);

                variableSistema = serviceVariableSistema.ConsultarElemento("DIASLIQ", "INDICA EL NÚMERO DE DIAS PERMITIDO EN UN VIAJE PARA SU LIQUIDACIÓN", 0, "15", true, usuario.Id.Login); 
                DateTime diaLimite = NUtileriasBB.ObtenerFechaServidor().AddDays(Convert.ToInt32(variableSistema.Valor_String) * -1);

                if (liquidacionesPendientes.Count >= liquidacionesPermitidas)
                    validacion = false;

                var liquidacionesPendientesExceden = liquidacionesPendientes.Where(i => i.Fecha <= diaLimite).ToList();
                var excedenString = string.Empty;
                if (liquidacionesPendientesExceden.Count() > 0)
                {
                    validacion = false;
                    excedenString = String.Join(",", liquidacionesPendientesExceden.Select(i => i.Id.Pk_Viaje).ToArray());
                }

                return (validacion,liquidacionesPermitidas,liquidacionesPendientes.Count(),excedenString,liquidacionesPendientesExceden);
            }
            catch (Exception ex)
            {
                throw new Exception(ex.Message);
            }
        }

