/// <summary>
        /// 
        /// </summary>
        /// <param name="request"></param>
        /// <param name="cancellationToken"></param>
        /// <returns></returns>
        public override async Task<Unit> Handle(IncidenciaNuevoRequest request, CancellationToken cancellationToken)
        {
            var fechaServidor = DateTimeServer.Now;

            if (request.ConductorId == null)
                throw new ArgumentException("Debe realizar la búsqueda de un conductor");

            if (request.FechaHoraIncidencia >= fechaServidor)
                throw new ArgumentException("No se pueden crear incidencias con fechas futuras.");

            if (request.Evidencias == null || request.Evidencias.Count == 0)
                throw new ArgumentException("Se necesita al menos un archivo adjunto para crear la incidencia.");

            var incidencia = Mapper.Map<IncidenciaConductor>(request);

            incidencia.FechaRegistra = fechaServidor.Date;
            incidencia.PersonalRegistraId = UserAccessor.LoggedPersonId;

            var incidenciaId = await Connection.RymInsertAsync(incidencia, cancellationToken);

            foreach (var evidencia in incidencia.Evidencias)
            {
                evidencia.IncidenciaConductorId = incidenciaId;
                await Connection.RymInsertAsync(evidencia, cancellationToken);
            }

            return Unit.Value;
        }

/// <summary>
        /// Consulta los vehículos registrados en tráfico (DB2).
        /// </summary>
        /// <returns>DataTable.</returns>
        private DataTable ConsultarVehiculosTrafico()
        {
            // Instancias y Definicion de criterios para consulta.
            var _usuario = (Session["SessionR1"] as Session).Usuario;
            var objNVehiculo = new NVehiculo();
            var serviceSeguridad = new NSeguridad();
            var gruposTrabajo = Session["gruposTrabajo"] != null ? 
                Session["gruposTrabajo"] as List<GrupoTrabajo> : serviceSeguridad.ObtenerGruposUsuario(_usuario.Id, _usuario.Id.Login);

            List<string> excluirVehiculos = new List<string>
            {
                StringEnum.GetStringValue(EstatusVehiculo.BAJA),
                StringEnum.GetStringValue(EstatusVehiculo.ROBADO),
                StringEnum.GetStringValue(EstatusVehiculo.VENDIDO),
                StringEnum.GetStringValue(EstatusVehiculo.AUTOFINANCIAMIENTO)
            };

            List<CriterioValor> listaCriteriosVehiculo = new List<CriterioValor>();
            listaCriteriosVehiculo.Add(new CriterioValor { Criterio = new Criterio { Alias = "VEHI", Campo = "ESTATUS" }, Operador = OperadoresLogicos.NOESTAEN, Valor = Utilerias.ObtenerCadenaCondicionIN(excluirVehiculos), OperadorCriterio = OperadoresBoleanos.AND });

            // Consulta.
            var listaVehiculos = objNVehiculo.ConsultaElementosVehiculos(_usuario, listaCriteriosVehiculo, EsAdministrador, gruposTrabajo);

            return listaVehiculos;
        }

/// <summary>
        /// Carga los conductores.
        /// </summary>
        /// <param name="esFiltro">Indica si la los conductores se cargan en el combo del Filtro.</param>
        private void CargaConductores(bool esFiltro, out object cond)
        {
            List<CriterioValor> _listaCriteriosConductor = new List<CriterioValor>();
            NConductor _serviceConductor = new NConductor();

            _listaCriteriosConductor.Add(new CriterioValor
            {
                Criterio = new Criterio
                {
                    Alias = "SUCURSAL",
                    Campo = "JURISDICCION_TRAFICO"
                },
                Operador = OperadoresLogicos.IGUAL,
                Valor = (Session["SessionR1"] as Session).Usuario.Id.Personal.Sucursal.jurisdiccionTrafico,
                OperadorCriterio = OperadoresBoleanos.AND
            });
            _listaCriteriosConductor.Add(new CriterioValor
            {
                Criterio = new Criterio
                {
                    Alias = "CONDUCTOR",
                    Campo = "ESTATUS"
                },
                Operador = OperadoresLogicos.IGUAL,
                Valor = StringEnum.GetStringValue(EstatusConductor.ACTIVO),
                OperadorCriterio = OperadoresBoleanos.AND
            });

            var consultaConductores = _serviceConductor.BuscaElementosGrid((Session["SessionR1"] as Session).Usuario.Id.Login, _listaCriteriosConductor);
            var listConductores = (from item in consultaConductores.AsEnumerable()
                                   select new { value = item[0], text = item[5] }).ToList().OrderBy(_i => _i.text);

            // Se asigna la variable que se utilizará fuera del contexto de la función.
            cond = listConductores;

            if (esFiltro)
            {
                var deConductores = (RibbonComboBoxItem)rbFiltros.Tabs[0].Groups[1].Items.FindByName("deConductores");

                foreach (var conductor in listConductores)
                {
                    deConductores.Items.Add(new ListEditItem
                    {
                        Value = conductor.value,
                        Text = conductor.text.ToString()
                    });
                }
            }
            else
            {
                cbConductor.DataSource = listConductores;
                cbConductor.DataBind();
            }
        }

