protected void callInicializar_Callback(object source, CallbackEventArgs e)
        {
            string seleccionRadioButton = e.Parameter;

            string fechaInicial = String.Empty;
            string fechaFinal = NUtileriasBB.ObtenerFechaServidor().ToString("dd/MM/yyyy"); ;

            switch (seleccionRadioButton)
            {
                case "0":
                    fechaInicial = GetFechaMesActual(NUtileriasBB.ObtenerFechaServidor());
                    break;
                case "1":
                    fechaInicial = UltimosDosMeses(NUtileriasBB.ObtenerFechaServidor());
                    break;
                case "2":
                    fechaInicial = UltimosTresMeses(NUtileriasBB.ObtenerFechaServidor());
                    break;
                case "3":
                    fechaInicial = GetFechaAnualActual(NUtileriasBB.ObtenerFechaServidor());
                    break;
            }

            e.Result = string.Format("{0},{1}", fechaInicial, fechaFinal);
        }

/// <summary>
        /// obtiene la fecha de dos meses atras
        /// </summary>
        /// <param name="FechaActual"></param>
        /// <returns></returns>
        private string UltimosDosMeses(DateTime FechaActual)
        {
            DateTime dosMese = FechaActual.AddMonths(-2);
            return new DateTime(dosMese.Year, dosMese.Month, 1).ToString("dd/MM/yyyy");
        }

