        /// </summary>
        /// <param name="aspxIndicador">El indicador a modificar.</param>
        private void ActualizarTipoSiniestro(ASPxDataUpdateValues aspxIndicador)
        {
            var negocio = new NTipoSiniestro();
            var tipoSiniestro = new TipoSiniestro
            {
                Id = new IDTipoSiniestro { Pk_Tipo_Siniestro = (int)aspxIndicador.Keys["ID.Pk_Tipo_Siniestro"] },
                Clave = (string)aspxIndicador.NewValues["Clave"],
                Nombre = (string)aspxIndicador.NewValues["Nombre"],
                Estatus = (string)aspxIndicador.NewValues["Estatus"],
                Au_Usuario = (Session["SessionR1"] as Session).Usuario.Id.Login,
                Au_Terminal = Request.UserHostName,
                Au_Borrado = 0
            };


            var tipoSiniestroAffter = negocio.ConsultarElemento(tipoSiniestro.Id);

            if (tipoSiniestroAffter.Estatus != tipoSiniestro.Estatus && tipoSiniestroAffter.Nombre == tipoSiniestro.Nombre)
                negocio.ModificarElemento(tipoSiniestro);

            if (tipoSiniestroAffter.Estatus != tipoSiniestro.Estatus && tipoSiniestroAffter.Nombre != tipoSiniestro.Nombre)
                ShowMessageError($"Se intento modificar el nombre y el estatus de uno o más registros, no es posible guardar cambios ya que puede generar inconsistencia en los datos");


            if (tipoSiniestroAffter.Nombre != tipoSiniestro.Nombre && tipoSiniestroAffter.Estatus == tipoSiniestro.Estatus)
            {
                //validar que no exista otro registro con ese nombre
                bool existe = negocio.ExisteTipoSiniestroUpdate(tipoSiniestro, (Session["SessionR1"] as Session).Usuario.Id.Login);

                if (!existe)
                    negocio.ModificarElemento(tipoSiniestro);
                else
                    ShowMessageError("No es posible registrar los cambios, ya existe otro registro con esa clave o nombre");
            }
        }

