private void ProcesaPolizas(List<Poliza> lista)
        {
            NPoliza _objNegocio = new NPoliza();
            List<Poliza> Invalida = new List<Poliza>();
            List<Poliza> Valida = new List<Poliza>();
            List<Poliza> _polizasToRemove = new List<Poliza>();
            var _fechaActual = NUtileriasBB.ObtenerFechaServidor().Date;

            if(lista.Count > 0)
            {
                foreach(var obj in lista)
                {
                    if(obj.Invalido == true)
                        Invalida.Add(obj);

                    else if(!(obj.Fecha_Vencimiento.Year > obj.Fecha_Renovacion.Year))
                        Invalida.Add(obj);

                    else
                        Valida.Add(obj);
                }

                if (Valida.Count > 0)
                {
                    var terminal = Request.UserHostName;
                    var usuario = (Session["SessionR1"] as Session).Sesion.Usuario.Id.Login;

                    var _validaGrouped = Valida.GroupBy(_i => _i.Vehiculo.Id.Pk_Vehiculo);
                    var _validaGroupedList = _validaGrouped.Where(_i => _i.Count() > 1)?.ToList();
                    if(_validaGroupedList.Count() > 0)
                    {
                        _validaGroupedList.ForEach(_i => _i.ToList().ForEach(j => Valida.Remove(j)));
                        _validaGroupedList.ForEach(_i => _i.ToList().ForEach(j => Invalida.Add(j)));
                    }

                    foreach(var item in Valida)
                    {
                        var _noValido = ValidaRegistroDuplicado(item.Vehiculo.Id.Pk_Vehiculo, item.Fecha_Vencimiento, item.Fecha_Renovacion);
                        if(_noValido)
                            _polizasToRemove.Add(item);
                    }

                    _polizasToRemove.ForEach(_i => Invalida.Add(_i));
                    _polizasToRemove.ForEach(_i => Valida.Remove(_i));
                    _polizasToRemove.Clear();

                    if(Valida.Count > 0)
                        _objNegocio.AgregarCargaMasiva(Valida, _fechaActual);
                }

                if (Invalida.Count > 0)
                    CrearWoorkBook(Invalida);
            }
        }

