/// <summary>
        /// Implementa las reglas de negocio y define cual es la sucursal que debe entregar el gasto.
        /// </summary>
        public Sucursal MetodoDefineGasto(string jurisdiccionTrafico)
        {
            //Valida vendedor polietilenos.
            NVendedor serviceVendedor = new NVendedor();
            var vendedor = serviceVendedor.ConsultaElementoPrimario(pedidoCliente.Id, usuario);
            bool vendedorPolitilenos = vendedor != null ? vendedor.Sucursal.Id.Pk_sucursal == 9 : false;

            if (jurisdiccionTrafico == "CORP")
            {
                //Pedido fiscal.
                if (pedidoCliente.Consignacion == 0)
                {
                    //if (vendedorPolitilenos)
                    //{
                        //pedido politilenos.
                      //  return new Sucursal { Id = new IDSucursal { Pk_sucursal = 9 } };
                    //}
                    //else
                    //{
                        //Pedido configurado.
                        if (EsConfigurado)
                        {
                            //Valida ciudad de la configuración del pedido.
                            if (pedidoCliente.Sucursal.Ciudad.Id.Pk_Ciudad != pedidoInterplanta.Sucursal.Ciudad.Id.Pk_Ciudad)
                            {
                                //Configurado diferente ciudad, gasto en sucursal que embarca.
                                return pedidoInterplanta.Sucursal;
                            }
                            else
                            {
                                //Configurado misma ciudad, gasto en sucursal que factura.
                                return pedidoCliente.Sucursal;
                            }
                        }
                        else
                        {
                            //No configurado, gasto en sucursal que factura.
                            return pedidoCliente.Sucursal;
                        }
                    //}
                }
                else //Pedido consignación.
                {
                    if (vendedorPolitilenos)
                    {
                        //Validación de cliente, si es nulo envia a polietilenos, sino envia a lo que determina el cliente.
                        _permiteEditar = true;//Activa la edición del viaje desde la pantalla de ventas.
                        NCliente serviceCliente = new NCliente();
                        var clienteTemp = serviceCliente.CargarElemento(pedidoCliente.ClienteDomicilioEntrega.Cliente.Id, usuario);

                        if (clienteTemp != null && clienteTemp.SucursalGasto != null && clienteTemp.SucursalGasto.Id != null && clienteTemp.SucursalGasto.Id.Pk_sucursal != 0)
                        {
                            return clienteTemp.SucursalGasto;
                        }
                        else
                        {
                            return new Sucursal { Id = new IDSucursal { Pk_sucursal = 9 } };
                        }
                    }
                    else
                    {
                        return pedidoInterplanta.Sucursal;
                    }
                }
            }
            else
            {
                return pedidoInterplanta.Sucursal;
            }

        }

