        private DataTable GetDataTableDocumentacion()
        {
            DataTable dttDocumentosLiquidacion = new DataTable();
            dttDocumentosLiquidacion.Clear();

            //Cabeceras
            dttDocumentosLiquidacion.Columns.Add("Id", typeof(Int32));
            dttDocumentosLiquidacion.Columns.Add("Fecha", typeof(DateTime));
            dttDocumentosLiquidacion.Columns.Add("Titulo", typeof(String));
            dttDocumentosLiquidacion.Columns.Add("Descripcion", typeof(string));
            dttDocumentosLiquidacion.Columns.Add("Archivo", typeof(byte[]));
            dttDocumentosLiquidacion.Columns.Add("Extension", typeof(string));
            dttDocumentosLiquidacion.Columns.Add("EsNuevo", typeof(Boolean));
            dttDocumentosLiquidacion.Columns.Add("EsEliminado", typeof(Boolean));

            DataColumn[] keyColumns = new DataColumn[1];
            keyColumns[0] = dttDocumentosLiquidacion.Columns["Id"];
            dttDocumentosLiquidacion.PrimaryKey = keyColumns;

            return dttDocumentosLiquidacion;
        }

