protected void cbDatos_Callback(object source, CallbackEventArgs e)
        {
            string pk_vehiculo = e.Parameter;

            if (pk_vehiculo != string.Empty)
            {
                NVehiculo nVehiculo = new NVehiculo();

                try
                {                  
                    var valor = int.Parse(string.Format("{0}", pk_vehiculo));
                    var vehiculo = nVehiculo.ConsultaElementoVehiculo(new IDVehiculo { Pk_Vehiculo = valor });
                    e.Result = vehiculo != null ? vehiculo.Numero_Placas.Trim() : string.Empty;
                }
                catch (Exception ex)
                {
                    throw new Exception(ex.Message);
                }
            }
        }

